namespace TsfBenchmark;

/**
 * Keep generated detail HTML inert until its own disclosure is opened.
 *
 * JSON_HEX_TAG prevents data from terminating its inert script element. The
 * fragment contains only HTML generated by the escaping report renderer.
 *
 * @param string $label    Disclosure label.
 * @param string $fragment Generated report HTML, with text already escaped.
 * @return string Native disclosure, empty content slot, and inert payload.
 */
function report_compact_fold( string $label, string $fragment ): string {

	return '<details class="report-fold"><summary>' . report_escape( $label ) . '</summary><div class="panel-slot"><p>Open this section to load its details.</p></div><script type="application/json" data-fragment>' . json_encode(
		$fragment,
		\JSON_HEX_TAG | \JSON_HEX_AMP | \JSON_HEX_APOS | \JSON_HEX_QUOT | \JSON_INVALID_UTF8_SUBSTITUTE | \JSON_THROW_ON_ERROR,
	) . '</script></details>';
}

/**
 * Draw aligned linear charts without inventing unavailable confidence bounds.
 *
 * Both axes include zero. Missing observations remain visibly unresolved.
 *
 * @param array $analysis Saved paired analysis.
 * @param bool  $gain     Plot direct differences and their intervals instead of additions.
 * @return string Accessible chart with text values for every configuration.
 */
function report_compact_chart( array $analysis, bool $gain ): string {

	$anchor = $analysis['comparison']['anchor'];
	$names  = array_column( $analysis['arms'], 'name', 'id' );
	$rows   = [];
	$bounds = [ 0.0 ];
	foreach ( $analysis['arms'] as $arm ) {
		$id = $arm['id'];
		if ( \in_array( $id, [ 'core-a', 'core-b' ], true ) || ( $gain && $id === $anchor ) ) continue;
		$comparison = $analysis['comparisons'][ $id ] ?? [];
		$value      = $gain ? ( $comparison['gain_ms'] ?? null ) : ( $analysis['paired']['points_added_ms']['overall'][ $id ] ?? null );
		$interval   = $gain ? ( $comparison['gain_interval'] ?? [] ) : [];
		$rows[]     = [
			'id'       => $id,
			'value'    => $value,
			'interval' => $interval,
		];
		foreach ( [ $value, $interval['low_ms'] ?? null, $interval['high_ms'] ?? null ] as $number ) {
			if ( null !== $number && is_finite( (float) $number ) ) $bounds[] = (float) $number;
		}
	}
	usort( $rows, fn( array $a, array $b ): int => ( $a['value'] ?? \INF ) <=> ( $b['value'] ?? \INF ) );
	$minimum                             = min( $bounds );
	$maximum                             = max( $bounds );
	$step                                = 10 ** floor( log10( max( 1, $maximum - $minimum ) ) );
	$minimum                             = floor( $minimum / $step ) * $step;
	$maximum                             = ceil( $maximum / $step ) * $step;
	if ( $maximum <= $minimum ) $maximum = $minimum + 1;
	$width                               = $maximum - $minimum;
	$position                            = static fn( float $value ): float => 100 * ( $value - $minimum ) / $width;
	$zero                                = $position( 0.0 );
	$title                               = $gain ? 'Direct advantage over each comparator' : 'Estimated time added by each plugin';
	$html                                = '<figure class="comparison-chart"><figcaption><h2>' . report_escape( $title ) . '</h2></figcaption>';
	$html                               .= $gain
		? '<p class="muted">Comparator addition minus ' . report_escape( $names[ $anchor ] ?? $anchor ) . ' addition. Positive favors the anchor. Lines show primary approximate simultaneous intervals; dots show estimates.</p>'
		: '<p class="muted">Added HTTP response time versus WordPress-only controls. Lower is less added time. One shared linear scale, including zero; these are not CPU self-times or whole-page load times.</p>';
	$html                               .= '<div class="chart-axis" aria-hidden="true"><span>' . report_number( $minimum, ' ms' ) . '</span><span>' . report_number( $maximum, ' ms' ) . '</span></div><ol class="chart-rows">';
	foreach ( $rows as $row ) {
		$value    = $row['value'];
		$interval = $row['interval'];
		$style    = '--zero:' . \sprintf( '%.5F', $zero ) . '%;';
		$reading  = report_number( $value, ' ms' );
		$mark     = '';
		if ( null !== $value && is_finite( (float) $value ) ) {
			$point = $position( (float) $value );
			if ( $gain ) {
				if ( isset( $interval['low_ms'], $interval['high_ms'] ) ) {
					$left  = $position( $interval['low_ms'] );
					$mark .= '<span class="range" style="left:' . \sprintf( '%.5F', $left ) . '%;width:' . \sprintf( '%.5F', $position( $interval['high_ms'] ) - $left ) . '%"></span>';
				}
				$mark    .= '<span class="dot" style="left:' . \sprintf( '%.5F', $point ) . '%"></span>';
				$reading .= '<small>' . report_paired_interval( $interval ) . '</small>';
			} else {
				$mark = '<span class="bar" style="left:' . \sprintf( '%.5F', min( $zero, $point ) ) . '%;width:' . \sprintf( '%.5F', abs( $point - $zero ) ) . '%"></span>';
			}
		}
		$html .= '<li class="chart-row' . ( $row['id'] === $anchor ? ' anchor-row' : '' ) . '"><span class="plugin-label">' . report_escape( $names[ $row['id'] ] ) . '</span><span class="track" style="' . $style . '" aria-hidden="true">' . $mark . '</span><span class="reading">' . $reading . '</span></li>';
	}
	return $html . '</ol></figure>';
}

/**
 * Deduplicate visible qualifications while retaining full scoped evidence below.
 *
 * @param array $analysis Saved analysis and public environment conditions.
 * @return string Compact list of limitations and validity warnings.
 */
function report_compact_warnings( array $analysis ): string {

	$conditions = [];
	$collect    = static function ( array $node ) use ( &$collect, &$conditions ): void {
		foreach ( $node['conditions'] ?? [] as $condition ) {
			if ( ! \is_array( $condition ) || ! \is_string( $condition['message'] ?? null ) ) continue;
			$message                = $condition['message'];
			$conditions[ $message ] = ( $conditions[ $message ] ?? 0 ) + 1;
		}
		foreach ( $node as $key => $child )
			if ( 'conditions' !== $key && \is_array( $child ) ) $collect( $child );
	};
	$collect( $analysis['environment'] );
	$issues = $analysis['reasons'];
	$timing = 0;
	foreach ( $analysis['passes'] as $pass ) {
		$issues = array_merge( $issues, $pass['reasons'] );
		foreach ( $pass['routes'] as $route ) {
			foreach ( $route['arms'] as $id => $arm ) {
				$issues      = array_merge( $issues, $arm['reasons'] ?? [] );
				if ( ! \in_array( $id, [ 'core-a', 'core-b' ], true ) )
					$timing += \count( $arm['timing_warnings'] ?? [] );
			}
		}
	}
	$html   = '<aside class="qualifications"><h2>Keep these limits in view</h2><ul><li>Results describe this fixed workload and observed session. They do not establish performance on every website or machine.</li><li>Threshold conclusions use all declared sensitivities and pass checks, not just the primary intervals plotted above.</li><li>' . \count( $analysis['passes'] ) . ' passes were observed; future-session uncertainty remains weakly measured. Circular resampling assumes approximate stationarity and cannot remove drift or systematic bias.</li>';
	$splits = [];
	foreach ( $analysis['paired']['diagnostics']['passes'] ?? [] as $pass )
		if ( isset( $pass['absolute_odd_even_mean_split_ms']['median'] ) ) $splits[] = $pass['absolute_odd_even_mean_split_ms']['median'];
	if ( $splits )
		$html .= '<li>Odd/even timing splits have pass medians of ' . report_number( min( $splits ), ' ms' ) . ' to ' . report_number( max( $splits ), ' ms' ) . '. Their cause is unknown; the timing diagnostics remain available below.</li>';
	foreach ( array_unique( $issues ) as $issue ) $html .= '<li>' . report_escape( $issue ) . '</li>';
	foreach ( $conditions as $message => $count )
		$html .= '<li>' . report_escape( $message ) . ( 1 < $count ? ' <span class="muted">(' . (int) $count . ' scoped records)</span>' : '' ) . '</li>';
	$html     .= '<li>' . (int) $timing . ' timing warnings in plugin/route/pass rows remain recorded. Negative cells are retained; full diagnostics are available below.</li>';
	return $html . '</ul></aside>';
}

/**
 * Nest route disclosures so opening one route does not instantiate every table.
 *
 * @param string $fragment Generated route section with fixed heading boundaries.
 * @return string Per-pass and per-route disclosures with inert table payloads.
 */
function report_compact_routes( string $fragment ): string {

	$html   = '<p>Open a pass, then a route. Each table loads independently.</p>';
	$passes = explode( '<h3>Pass ', $fragment );
	array_shift( $passes );
	foreach ( $passes as $pass ) {
		$id      = (int) $pass;
		$routes  = explode( '<h4>', $pass );
		$intro   = array_shift( $routes );
		$end     = strpos( $intro, '</h3>' );
		$content = false === $end ? '' : substr( $intro, $end + 5 );
		foreach ( $routes as $route ) {
			$end = strpos( $route, '</h4>' );
			if ( false === $end ) continue;
			$label    = html_entity_decode( substr( $route, 0, $end ), \ENT_QUOTES, 'UTF-8' );
			$content .= report_compact_fold( $label, substr( $route, $end + 5 ) );
		}
		$html .= report_compact_fold( 'Pass ' . $id, $content );
	}
	return $html;
}

/**
 * Render a compact overview and independently deferred detailed sections.
 *
 * Saved numerical inputs are never recalculated. The expanded renderer remains
 * unchanged for historical replay and the no-JavaScript details page.
 *
 * @param array $analysis Saved version 2 paired analysis.
 * @return string Standalone compact presentation with embedded assets.
 */
function render_compact_report( array $analysis ): string {

	$context     = $analysis['analysis_context'] ?? [];
	$css         = file_get_contents( __DIR__ . '/compact-report.css' );
	$js          = file_get_contents( __DIR__ . '/compact-report.js' );
	$title       = report_escape( $analysis['name'] );
	$html        = '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' . $title . '</title><style>' . $css . '</style><body><main><header><p class="eyebrow">WordPress plugin benchmark · paired analysis ' . report_escape( $analysis['analysis_version'] ) . '</p><h1>' . $title . '</h1><p class="verdict">' . report_escape( str_replace( '_', ' ', $analysis['verdict'] ) ) . ' <span>in this session</span></p>';
	$anchor_name = array_column( $analysis['arms'], 'name', 'id' )[ $analysis['comparison']['anchor'] ];
	$html       .= '<p>Threshold evaluated: each comparator adds at least <strong>' . report_escape( (string) $analysis['comparison']['threshold'] ) . '×</strong> the estimated response time added by ' . report_escape( $anchor_name ) . '.</p>';
	if ( ! empty( $context['retrospective'] ) )
		$html   .= '<p class="retrospective"><strong>Retrospective reanalysis, not independent confirmation.</strong> The original ' . report_escape( $context['source_analysis_version'] ) . ' result was ' . report_escape( $context['source_verdict'] ) . '; it remains preserved.</p>';
	$measured    = 0;
	foreach ( $analysis['paired']['diagnostics']['passes'] ?? [] as $pass ) $measured += $pass['counts']['measured_rows'];
	$html .= '<p class="run-facts">' . \count( $analysis['routes'] ) . ' frontend HTML routes · ' . \count( $analysis['passes'] ) . ' passes · ' . ( $measured ? number_format( $measured ) . ' measured requests' : 'measured count unresolved' ) . '</p></header>';
	$html .= report_compact_chart( $analysis, false );
	$html .= report_compact_chart( $analysis, true );
	$html .= '<p class="interval-note">Primary approximate ' . report_number( 100 * $analysis['comparison']['confidence'], '%' ) . ' simultaneous interval estimates. The shared controls cancel in the direct differences. A ratio above 1 means the comparator added more response time on this aggregate; it is not a ratio of whole-page loading speeds.</p>';
	$html .= report_compact_warnings( $analysis );
	$html .= '<section class="detail-index"><h2>Detailed evidence</h2><p>Details load only when opened and are released when closed. <a href="details.html">Open the full expanded report</a> or <a href="summary.json">read the saved analysis JSON</a>.</p><noscript><p>JavaScript is disabled. The charts and qualifications above remain available; use the full expanded report for detailed tables.</p></noscript>';
	// The historical renderer emits flat sections with escaped text. Split only its fixed boundaries.
	$sections = explode( '<section>', render_paired_report( $analysis ) );
	array_shift( $sections );
	foreach ( $sections as $section ) {
		$end = strpos( $section, '</section>' );
		if ( false === $end ) continue;
		$fragment    = substr( $section, 0, $end );
		$heading_end = strpos( $fragment, '</h2>' );
		if ( false === $heading_end ) continue;
		$label   = html_entity_decode( substr( $fragment, 4, $heading_end - 4 ), \ENT_QUOTES, 'UTF-8' );
		$content = substr( $fragment, $heading_end + 5 );
		if ( 'Absolute HTTP responses and route additions' === $label ) $content = report_compact_routes( $content );
		$html .= report_compact_fold( $label, $content );
	}
	return $html . '</section><footer>Estimated added HTTP response time · fixed route weights · analysis ' . report_escape( $analysis['analysis_version'] ) . ' · compact presentation 1</footer></main><script type="module">' . $js . '</script></body></html>';
}
